draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 - 20 + 15 * Math.cos(t), H/2 + 80);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 + 20 + 15 * Math.cos(t), H/2 + 80);
  ctx.stroke();

  // life event changing moment
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('?', W/2 + 50 * Math.sin(t), H/2 - 50);

  ctx.restore();
}
